#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

struct buffer {
    char *data;
    size_t size;
};

struct buffer *alloc_buffer(size_t elem_size, size_t count) {
    if (elem_size == 0 || count == 0) return NULL;
    if (count > SIZE_MAX / elem_size) return NULL;
    struct buffer *buf = malloc(sizeof(struct buffer));
    if (buf == NULL) return NULL;
    buf->size = elem_size * count;
    buf->data = malloc(buf->size);
    if (buf->data == NULL) { free(buf); return NULL; }
    memset(buf->data, 0, buf->size);
    return buf;
}

int main(int argc, char **argv) {
    if (argc < 3) return 1;
    size_t elem = strtoul(argv[1], NULL, 10);
    size_t cnt = strtoul(argv[2], NULL, 10);
    struct buffer *buf = alloc_buffer(elem, cnt);
    if (buf) { free(buf->data); free(buf); }
    return 0;
}

import java.security.SecureRandom;
import java.util.Base64;

public class SecureTokenGenerator {
    private static final int TOKEN_LENGTH_BYTES = 32;
    private final SecureRandom secureRandom;

    public SecureTokenGenerator() {
        // 使用系统提供的安全随机源
        this.secureRandom = new SecureRandom();
    }

    /**
     * 生成用于密码重置的会话令牌
     * @return Base64编码的安全令牌
     */
    public String generatePasswordResetToken() {
        byte[] tokenBytes = new byte[TOKEN_LENGTH_BYTES];
        // 使用SecureRandom填充随机字节
        secureRandom.nextBytes(tokenBytes);
        // Base64编码以便在URL和数据库中安全存储
        return Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes);
    }

    /**
     * 验证令牌是否符合安全要求（示例用途）
     * @param token 待验证的令牌
     * @return 令牌是否有效
     */
    public boolean isValidTokenFormat(String token) {
        if (token == null || token.length() < 32) {
            return false;
        }
        // 检查是否为有效的Base64 URL编码字符
        return token.matches("^[A-Za-z0-9_-]+$");
    }
}

const express = require('express');
const app = express();

// User profile data store (simulated)
const userProfiles = {
  'alice': { name: 'Alice', bio: 'Security researcher' },
  'bob': { name: 'Bob', bio: 'Frontend developer' }
};

// Middleware to parse JSON bodies
app.use(express.json());

// Route to fetch user profile
app.get('/profile/:username', (req, res) => {
  const username = req.params.username;

  // Validate username against whitelist pattern
  if (!/^[a-zA-Z0-9_]{1,20}$/.test(username)) {
    return res.status(400).json({ error: 'Invalid username format' });
  }

  const profile = userProfiles[username];
  if (!profile) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Set Content-Type to text/plain to prevent HTML rendering
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');

  // Send user-controlled data as plain text (not HTML)
  res.send(`Name: ${profile.name}\nBio: ${profile.bio}`);
});

// Route that echoes user input directly
app.post('/echo', (req, res) => {
  const userInput = req.body.input || '';

  // Validate input length and characters
  if (typeof userInput !== 'string' || userInput.length > 500) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  // Set Content-Type to text/plain to prevent XSS via HTML rendering
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');

  // Echo user input as plain text - safe because browser won't render as HTML
  res.send(userInput);
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

