public class AuthCheckSafe {
    private static final int MAX_REQUESTS = 1000;

    // 校验请求次数限制（防止暴力破解）
    public static boolean checkLimit(int requestCount, int increment) {  // line 6: 输入
        if (requestCount < 0 || increment < 0) return false;  // line 7: 下限校验
        try {
            // 使用 Math.addExact 检测溢出
            int newCount = Math.addExact(requestCount, increment);  // line 10: 溢出检测
            if (newCount > MAX_REQUESTS) {  // line 11: 上限校验
                return false;
            }
            return true;
        } catch (ArithmeticException e) {
            return false;  // line 16: 溢出时拒绝
        }
    }
}

// Java 服务：用 ConcurrentHashMap + 同步块保护共享状态
import java.util.concurrent.*;
import java.util.*;

public class OrderService {
    // 安全：使用并发安全的 ConcurrentHashMap
    private final ConcurrentHashMap<String, Order> orders = new ConcurrentHashMap<>();  // line 6
    private final Object approvalLock = new Object();   // line 7

    public String createOrder(String user, int amount) {
        String orderId = UUID.randomUUID().toString();
        Order o = new Order(user, amount);
        // 安全：put 是原子的
        orders.put(orderId, o);                          // line 13
        // 安全：审批状态用同步块保护读改写
        synchronized (approvalLock) {                    // line 15
            if (amount > 1000) {
                o.status = "pending_approval";
            } else {
                o.status = "confirmed";
            }
        }
        return orderId;
    }

    public void updateAmount(String orderId, int delta) {
        // 安全：compute 是原子的，避免读改写竞态
        orders.computeIfPresent(orderId, (k, v) -> {      // line 24
            v.amount += delta;
            return v;
        });
    }

    static class Order {
        String user; int amount; String status;
        Order(String u, int a) { user = u; amount = a; }
    }
}

